#!/usr/bin/env bash
# 200-locus timing/failure pilot + known-direction controls of all tier-1 baselines on the validation screening set
# screen_v2 (DESIGN v4 §4.3, §7.1 item 9). Usage (from the project root, in the background, log in logs/baselines/):
#   bash src/baselines/benchmarks/run_pilot_v2.sh data/processed/sets/screen_v2.h5 > logs/baselines/pilot_v2.log 2>&1
# Do not edit this file while it runs.
set -euo pipefail
SET=${1:?locus set}
ROOT=$(cd "$(dirname "$0")/../../.." && pwd)
cd "$ROOT"
source env/activate.sh
export PYTHONPATH=src
STEM=$(basename "$SET" .h5)
B=src/baselines/benchmarks
MEM=${MEM_BUDGET_GB:-48}
CPU=${MAX_CPUS:-24}
RES=${RESULTS_DIR:-results/baselines_pilot}

echo "[$(date -u +%FT%TZ)] sample 200 pilot ids"
python -m baselines.pilot sample --set "$SET" --out "$B/pilot200_${STEM}_ids.txt" --n 200
echo "[$(date -u +%FT%TZ)] select control ids"
python tests/baselines/pilot/controls.py select --set "$SET" --out "tests/baselines/pilot/controls_${STEM}_ids.txt"

echo "[$(date -u +%FT%TZ)] pilot runs"
python -m baselines.pilot run --set "$SET" --ids-file "$B/pilot200_${STEM}_ids.txt" --tag "pilot200_${STEM}" \
  --mem-budget-gb "$MEM" --max-cpus "$CPU" --results-dir "$RES"
python -m baselines.pilot summarise --runs "$B/pilot200_${STEM}_runs.json"

echo "[$(date -u +%FT%TZ)] control runs"
python -m baselines.pilot run --set "$SET" --ids-file "tests/baselines/pilot/controls_${STEM}_ids.txt" \
  --tag "controls_${STEM}" --mem-budget-gb "$MEM" --max-cpus "$CPU" --results-dir "$RES"
python tests/baselines/pilot/controls.py analyse --runs "$B/controls_${STEM}_runs.json" \
  --out "$B/controls_${STEM}.tsv"
echo "[$(date -u +%FT%TZ)] done"
